-- banking_project_mysql_perfect.sql
-- Generated dataset: 10-table banking project

SET FOREIGN_KEY_CHECKS=0;

CREATE DATABASE IF NOT EXISTS banking_project_db;
USE banking_project_db;


-- Tables
DROP TABLE IF EXISTS customer_feedback;
DROP TABLE IF EXISTS fraud_alerts;
DROP TABLE IF EXISTS credit_cards;
DROP TABLE IF EXISTS loans;
DROP TABLE IF EXISTS kyc_documents;
DROP TABLE IF EXISTS transactions;
DROP TABLE IF EXISTS accounts;
DROP TABLE IF EXISTS staff;
DROP TABLE IF EXISTS branches;
DROP TABLE IF EXISTS customers;

CREATE TABLE customers (
    customer_id INT PRIMARY KEY,
    first_name VARCHAR(50),
    last_name VARCHAR(50),
    dob DATE,
    gender CHAR(1),
    email VARCHAR(100),
    phone VARCHAR(20),
    address VARCHAR(200),
    city VARCHAR(50),
    state VARCHAR(50),
    pincode VARCHAR(10),
    kyc_status VARCHAR(20),
    risk_profile VARCHAR(10),
    created_at DATETIME
);

CREATE TABLE branches (
    branch_id INT PRIMARY KEY,
    branch_name VARCHAR(100),
    branch_city VARCHAR(50),
    branch_state VARCHAR(50),
    branch_manager_id INT
);

CREATE TABLE staff (
    staff_id INT PRIMARY KEY,
    branch_id INT,
    first_name VARCHAR(50),
    last_name VARCHAR(50),
    role VARCHAR(50),
    join_date DATE,
    salary INT
);

CREATE TABLE accounts (
    account_id INT PRIMARY KEY,
    customer_id INT,
    account_type VARCHAR(20),
    branch_id INT,
    opening_date DATE,
    balance DECIMAL(15,2),
    aml_flag TINYINT,
    status VARCHAR(20)
);

CREATE TABLE transactions (
    transaction_id INT PRIMARY KEY,
    account_id INT,
    transaction_date DATETIME,
    transaction_type VARCHAR(10),
    amount DECIMAL(15,2),
    mode VARCHAR(20),
    counterparty VARCHAR(100),
    suspicious_flag TINYINT,
    remarks VARCHAR(255)
);

CREATE TABLE kyc_documents (
    document_id INT PRIMARY KEY,
    customer_id INT,
    document_type VARCHAR(50),
    document_number VARCHAR(50),
    issued_date DATE,
    expiry_date DATE,
    verification_status VARCHAR(20)
);

CREATE TABLE loans (
    loan_id INT PRIMARY KEY,
    customer_id INT,
    loan_type VARCHAR(50),
    loan_amount DECIMAL(15,2),
    interest_rate DECIMAL(5,2),
    start_date DATE,
    end_date DATE,
    repayment_status VARCHAR(20)
);

CREATE TABLE credit_cards (
    card_id INT PRIMARY KEY,
    customer_id INT,
    card_type VARCHAR(50),
    issue_date DATE,
    expiry_date DATE,
    credit_limit DECIMAL(15,2),
    current_usage DECIMAL(15,2)
);

CREATE TABLE fraud_alerts (
    alert_id INT PRIMARY KEY,
    transaction_id INT,
    alert_date DATETIME,
    alert_type VARCHAR(100),
    severity VARCHAR(20),
    resolution_status VARCHAR(20),
    resolved_by INT
);

CREATE TABLE customer_feedback (
    feedback_id INT PRIMARY KEY,
    customer_id INT,
    feedback_date DATETIME,
    feedback_text VARCHAR(500),
    sentiment VARCHAR(20)
);





































































SET FOREIGN_KEY_CHECKS=1;
